(1, 7733, N'SN_SKILL_EU_WAND_CLERIC_BASE', N'클레릭 기본공격', N'0', N'0', N'0', N'0', N'0', N'Cleric Basic Attack', N'0', N'0', N'0', N'0', N'0', N'0', N'0'),
(1, 7734, N'EU_CLERIC_GROUP_GLORY_TT_DESC', N'글로리

